    linear_coefficient = rng.randint(1, modulus - 1)
    constant_term = rng.randint(0, modulus - 1)
    parameters = {"modulus": modulus, "linear_coefficient": linear_coefficient, "constant_term": constant_term}
    answer = set()
    for x in range(modulus):
        if (x**2 + linear_coefficient * x + constant_term) % modulus == 0:
            answer.add(x)
    check = set()
    for x in range(modulus):
        if (x**2 + linear_coefficient * x + constant_term) % modulus == 0:
            check.add(x)
