import fractions

def build_instance(rng):
    n = rng.randint(4, 6)
    k = n // 2
    answer = sum(fractions.Fraction(1, 2) ** i for i in range(k + 1))
    check = 0
    for i in range(k + 1):
        check += fractions.Fraction(1, 2) ** i
    assert answer == check, f'answer={answer} check={check}'
    parameters = {"n": n, "k": k}
    return parameters, str(answer), str(check)
