def build_instance(rng):
    set_size = rng.randint(1, 5)
    answer = 2 ** (set_size - 1)
    subsets = list(itertools.combinations(range(set_size), range(set_size + 1)))
    check = 0
    for mask in range(1 << len(subsets)):
        chosen = {subset for index, subset in enumerate(subsets) if mask >> index & 1}
        disjoint = all((not subset1 & subset2 for subset1 in chosen for subset2 in chosen if subset1 != subset2))
        if disjoint:
            check = max(check, len(chosen))
    assert answer == check, f'answer={answer} check={check}'
    parameters = {'set_size': set_size}
    return (parameters, answer, check)



