    width = rng.randint(1, 10)

    def fibonacci(n):
        if n <= 1:
            return 1
        a, b = (1, 1)
        for _ in range(2, n + 1):
            a, b = (b, a + b)
        return a
    answer = fibonacci(length) * fibonacci(width)

