        if width == 1:
            return 1 + count_tilings(length - 1, width)
        return count_tilings(length - 1, width) + count_tilings(length, width - 1)
    check = count_tilings(length, width)
    parameters = {'length': length, 'width': width}
    return (parameters, answer, check)



